<script setup>
import { onMounted, ref, watch } from 'vue'
const props = defineProps({ api: { type: Function, required: true }, notes: { type: Array, required: true } })
const emit = defineEmits(['notify', 'open-note', 'reload-notes'])
const tab = ref('plan'), busy = ref(false), error = ref(''), tasks = ref([]), selectedDate = ref(localDate()), loaded = ref(false)
const question = ref(''), reply = ref(''), searchText = ref(''), hits = ref(null)
const chosenNote = ref(''), chunks = ref(null), job = ref(null), jobId = ref(''), sync = ref(null), syncMissing = ref(false)
const title = ref(''), file = ref(null), imported = ref(null), quiz = ref(null), selectedAnswer = ref(''), quizResult = ref(null)
function localDate() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }
function fail(e) { error.value = e.message || '操作失败，请稍后再试。' }
async function run(action) { if (busy.value) return; busy.value = true; error.value = ''; try { await action() } catch(e) { fail(e) } finally { busy.value = false } }
async function loadTasks() { await run(async () => { tasks.value = await props.api(`/study/tasks?date=${encodeURIComponent(selectedDate.value)}`); loaded.value = true }) }
async function generateTasks() { await run(async () => { const todayTasks = await props.api('/study/tasks/generate', { method:'POST' }); selectedDate.value = localDate(); tasks.value = todayTasks; loaded.value = true; emit('notify','今日复习计划已更新。') }) }
async function toggle(task) { await run(async () => { await props.api(`/study/tasks/${task.id}`, { method:'PUT', body:JSON.stringify({completed:!task.completed}) }); task.completed = !task.completed }) }
async function openQuiz(task) { await run(async () => { quiz.value = await props.api(`/quiz/${task.quizId}`); selectedAnswer.value = ''; quizResult.value = null }) }
async function answerQuiz() { if (!quiz.value || !selectedAnswer.value) return; await run(async () => { quizResult.value = await props.api(`/quiz/${quiz.value.quizId}/answer`, { method:'POST',body:JSON.stringify({answer:selectedAnswer.value}) }) }) }
async function ask() { if (!question.value.trim()) return; await run(async () => { reply.value = ''; reply.value = await props.api('/study/assistant', { method:'POST',body:JSON.stringify({message:question.value.trim()}) }) }) }
async function search() { if (!searchText.value.trim()) return; await run(async () => { hits.value = await props.api(`/notes/chunks/search?question=${encodeURIComponent(searchText.value.trim())}`) }) }
async function viewChunks() { if (!chosenNote.value) return; await run(async () => { chunks.value = await props.api(`/notes/${chosenNote.value}/chunks`) }) }
async function createJob() { if (!chosenNote.value) return; await run(async () => { const r = await props.api(`/notes/${chosenNote.value}/chunk-jobs`,{method:'POST'}); jobId.value = String(r.jobId); job.value = null; emit('notify',`片段任务 #${r.jobId} 已提交，请查询状态。`) }) }
async function queryJob() { if (!/^\d+$/.test(String(jobId.value)) || Number(jobId.value)<1) { error.value='请输入有效的任务编号。'; return } await run(async () => { job.value = await props.api(`/chunk-jobs/${jobId.value}`) }) }
async function retryJob() { if (!job.value) return; await run(async () => { await props.api(`/chunk-jobs/${job.value.id}/retry`,{method:'POST'}); job.value = await props.api(`/chunk-jobs/${job.value.id}`); emit('notify','片段任务已重新排队。') }) }
async function querySync() { if (!chosenNote.value) return; await run(async () => { syncMissing.value = false; try { sync.value = await props.api(`/notes/${chosenNote.value}/vector-sync`) } catch(e) { if (e.status === 404) { sync.value = null; syncMissing.value = true } else throw e } }) }
async function scheduleSync(retry = false) { if (!chosenNote.value) return; await run(async () => { await props.api(`/notes/${chosenNote.value}/vector-sync${retry ? '/retry' : ''}`,{method:'POST'}); sync.value = await props.api(`/notes/${chosenNote.value}/vector-sync`); syncMissing.value = false; emit('notify','同步任务已提交。') }) }
async function backfill() { await run(async () => { await props.api('/notes/vector-sync/backfill',{method:'POST'}); emit('notify','已提交缺失向量同步任务。') }) }
async function importText() { if (!file.value || !title.value.trim() || title.value.trim().length > 50) { error.value='请填写标题并选择 TXT 文件。'; return } if (!file.value.name.toLowerCase().endsWith('.txt') || file.value.size > 10240 || !file.value.size) { error.value='请选择不超过 10 KiB 的非空 UTF-8 TXT 文件。'; return } await run(async () => { const form=new FormData(); form.append('title',title.value.trim()); form.append('file',file.value); imported.value=await props.api('/notes/upload-async',{method:'POST',body:form}); jobId.value=String(imported.value.jobId); job.value=null; emit('reload-notes'); emit('notify','笔记已创建，片段任务正在后台处理。') }) }
function formatStatus(status) { return ({QUEUED:'排队中',PENDING:'等待处理',RUNNING:'处理中',SUCCEEDED:'已完成',FAILED:'失败'})[status] || status }
watch(chosenNote, () => { chunks.value=null; sync.value=null; syncMissing.value=false })
onMounted(loadTasks)
</script>
<template>
<main class="main-content study-page"><div class="page-heading"><div><div class="heading-label">✦ 学习与知识管理</div><h1>今天，从这里开始<span class="heading-period">.</span></h1><p>查看复习计划、搜索知识与管理笔记索引。</p></div></div>
<div class="study-tabs"><button v-for="item in [{id:'plan',name:'复习计划'},{id:'assistant',name:'学习助手'},{id:'search',name:'语义检索'},{id:'index',name:'笔记索引'},{id:'async',name:'后台导入'}]" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id;error=''">{{ item.name }}</button></div>
<p v-if="error" class="feature-error" role="alert">{{ error }}</p>
<div v-if="tab==='plan'" class="study-grid"><section class="study-card"><span class="study-eyebrow">DAILY REVIEW</span><h2>复习计划</h2><p>从最近一次仍答错的题目生成今天的任务。重复生成不会重复添加相同任务。</p><div class="feature-controls"><label>查看日期 <input v-model="selectedDate" type="date" @change="loadTasks"></label><button class="outline-button" :disabled="busy" @click="loadTasks">查询</button><button class="primary" :disabled="busy" @click="generateTasks">生成今日计划</button></div><div class="study-list"><p v-if="loaded && !tasks.length">这一天还没有任务。可以从错题生成今日计划。</p><div v-for="task in tasks" :key="task.id" class="feature-task"><label><input type="checkbox" :checked="task.completed" :disabled="busy" @change="toggle(task)"><span>{{ task.question }}</span></label><button class="text-button" :disabled="busy" @click="openQuiz(task)">开始答题 ↗</button></div></div></section><aside class="study-card study-question"><template v-if="quiz"><span class="study-eyebrow">复习题 #{{ quiz.quizId }}</span><h2>{{ quiz.question }}</h2><form @submit.prevent="answerQuiz"><label v-for="option in quiz.options" :key="option.label" class="quiz-option" :class="{chosen:selectedAnswer===option.label}"><input v-model="selectedAnswer" type="radio" name="review-answer" :value="option.label"><b>{{ option.label }}</b>{{ option.content }}</label><button class="primary" :disabled="busy || !selectedAnswer">提交答案</button></form><div v-if="quizResult" class="quiz-answer"><strong>{{ quizResult.correct ? '回答正确' : '再想一想' }} · 正确答案 {{ quizResult.correctAnswer }}</strong><p>{{ quizResult.explanation }}</p><small>完成任务需要手动勾选。</small></div></template><template v-else><h2>复习一点点，也很好</h2><p>选择计划中的题目，在这里完成练习。</p></template></aside></div>
<div v-else-if="tab==='assistant'" class="study-grid"><section class="study-card"><span class="study-eyebrow">STUDY ASSISTANT</span><h2>向学习助手提问</h2><p>助手可以结合你的学习数据回答；每次提问会调用模型。</p><form class="study-form" @submit.prevent="ask"><label>你的问题<textarea v-model="question" maxlength="2000" rows="5" placeholder="例如：我最近需要重点复习什么？"></textarea></label><button class="primary" :disabled="busy || !question.trim()">{{ busy ? '正在思考…' : '发送问题' }}</button></form><div v-if="reply" class="feature-output"><strong>助手回答</strong><p>{{ reply }}</p></div></section><aside class="study-card study-aside"><h2>一个问题，一步进展</h2><p>可以询问学习建议，也可以围绕已有学习内容提出具体问题。回答请结合原始资料核对。</p></aside></div>
<div v-else-if="tab==='search'" class="study-grid"><section class="study-card"><span class="study-eyebrow">SEMANTIC SEARCH</span><h2>搜索相关笔记片段</h2><p>输入想了解的内容，按语义查找当前账号的笔记片段。</p><form class="study-form" @submit.prevent="search"><label>搜索内容<textarea v-model="searchText" rows="3" placeholder="例如：接口和抽象类有什么区别？"></textarea></label><button class="primary" :disabled="busy || !searchText.trim()">{{ busy ? '检索中…' : '搜索片段' }}</button></form><div v-if="hits" class="study-list"><strong>检索结果 · {{ hits.length }} 条</strong><p v-if="!hits.length">没有找到符合条件的片段。请尝试换种表达或检查索引状态。</p><button v-for="hit in hits" :key="`${hit.noteId}-${hit.chunkIndex}`" class="feature-hit" @click="emit('open-note',hit)"><span><strong>{{ hit.noteTitle }} · 片段 {{ hit.chunkIndex }}</strong><small>相似度 {{ Number(hit.score).toFixed(3) }}</small><span>{{ hit.content }}</span></span> ↗</button></div></section><aside class="study-card study-aside"><h2>从意思出发</h2><p>语义检索可以找到表达不同但意思相近的内容。结果取决于笔记片段和索引状态。</p></aside></div>
<div v-else-if="tab==='index'" class="study-grid"><section class="study-card"><span class="study-eyebrow">NOTE INDEX</span><h2>查看笔记片段</h2><div class="study-form"><label>选择笔记<select v-model="chosenNote"><option value="">请选择笔记</option><option v-for="note in notes" :key="note.id" :value="note.id">{{ note.title }}</option></select></label><div class="study-actions"><button class="outline-button" :disabled="!chosenNote || busy" @click="viewChunks">查看片段</button><button class="outline-button" :disabled="!chosenNote || busy" @click="createJob">提交片段构建任务</button><button class="outline-button" :disabled="!chosenNote || busy" @click="querySync">查询向量同步</button></div><p>提交任务表示进入队列，完成情况以任务状态为准。</p></div><div v-if="chunks" class="study-list"><strong>片段 · {{ chunks.length }} 个</strong><p v-if="!chunks.length">暂无片段，可以提交构建任务。</p><div v-for="chunk in chunks" :key="chunk.chunkIndex" class="feature-output"><strong>片段 {{ chunk.chunkIndex }}</strong><p>{{ chunk.content }}</p></div></div><div v-if="sync || syncMissing" class="feature-output"><strong>向量同步：{{ sync ? formatStatus(sync.status) : '尚无任务' }}</strong><p v-if="sync">尝试 {{ sync.attempts }} 次<span v-if="sync.errorMessage"> · {{ sync.errorMessage }}</span><span v-if="sync.nextRetryAt"> · 下次重试 {{ sync.nextRetryAt.replace('T',' ') }}</span></p><div class="study-actions"><button class="outline-button" :disabled="busy" @click="scheduleSync(false)">提交同步</button><button v-if="sync?.status==='FAILED'" class="outline-button" :disabled="busy" @click="scheduleSync(true)">重试同步</button></div></div></section><aside class="study-card study-aside"><h2>后台任务</h2><p>可通过任务编号查询片段构建进度。</p><div class="study-form"><label>片段任务编号<input v-model="jobId" type="number" min="1" placeholder="输入任务编号"></label><button class="outline-button" :disabled="busy" @click="queryJob">查询任务</button></div><div v-if="job" class="feature-output"><strong>{{ formatStatus(job.status) }} · #{{ job.id }}</strong><p>笔记 #{{ job.noteId }} · 尝试 {{ job.attempts }} 次</p><p v-if="job.errorMessage">{{ job.errorMessage }}</p><button v-if="job.status==='FAILED'" class="outline-button" :disabled="busy" @click="retryJob">重试任务</button></div><hr class="feature-divider"><p>为当前账号缺少同步任务的笔记安排向量同步。</p><button class="outline-button" :disabled="busy" @click="backfill">补建缺失的同步任务</button></aside></div>
<div v-else class="study-grid"><section class="study-card"><span class="study-eyebrow">BACKGROUND IMPORT</span><h2>后台导入文本</h2><p>立即创建笔记，将向量和片段构建交给后台任务。</p><form class="study-form" @submit.prevent="importText"><label>笔记标题<input v-model="title" maxlength="50" placeholder="输入标题"></label><label>UTF-8 文本文件<input type="file" accept=".txt,text/plain" @change="file=$event.target.files[0] || null"></label><p>仅支持非空 TXT 文件，大小不超过 10 KiB。</p><button class="primary" :disabled="busy">{{ busy ? '提交中…' : '导入并创建任务' }}</button></form><div v-if="imported" class="feature-output"><strong>笔记 #{{ imported.noteId }} 已创建</strong><p>片段任务编号：{{ imported.jobId }}。处理可能需要一些时间。</p><button class="outline-button" @click="tab='index'">查看任务状态</button></div></section><aside class="study-card study-aside"><h2>继续做别的事</h2><p>提交后无需停留在这里。请记下任务编号，之后可以在“笔记索引”中查询或重试失败任务。</p></aside></div>
</main>
</template>
